import { existsSync, readdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { documentationSidebar } from "../navigation.mjs";

const SITE_ORIGIN = "https://docs.titanspan.invalid";

/**
 * Validate Starlight sidebar entries against published Markdown pages.
 *
 * The same sidebar definition drives Astro and this check. Autogenerated
 * directories count every nested page so new pages in an existing component
 * directory remain visible in navigation.
 *
 * @param {string} docsRoot Directory containing Starlight content pages.
 * @param {unknown} sidebar Starlight sidebar configuration.
 * @returns {string[]} Human-readable validation failures.
 */
export function validateDocumentationNavigation(docsRoot, sidebar) {
  const root = path.resolve(docsRoot);
  const errors = [];
  if (!Array.isArray(sidebar)) {
    return ["Starlight navigation must be a sidebar array."];
  }

  const pages = collectMarkdownPages(root);
  const pagesByRoute = new Map();
  for (const page of pages) {
    const relative = path.relative(root, page).split(path.sep).join("/");
    const route = routeForPage(relative);
    if (pagesByRoute.has(route)) {
      errors.push(`Multiple pages resolve to the route "/${route}".`);
    }
    pagesByRoute.set(route, relative);
  }

  const includedPages = new Map();
  const includePage = (route, source) => {
    const normalized = normalizeRoute(route);
    const page = pagesByRoute.get(normalized);
    if (page === undefined) {
      errors.push(`${source} route "${route}" does not resolve to a page.`);
      return;
    }
    if (includedPages.has(page)) {
      errors.push(
        `Duplicate sidebar destination "/${normalized}" targets ${page}.`,
      );
      return;
    }
    includedPages.set(page, source);
  };

  /**
   * Visit one level of Starlight sidebar entries.
   *
   * @param {unknown[]} items Sidebar items to inspect.
   * @param {string} source Sidebar location for error reporting.
   * @returns {void}
   */
  function visit(items, source) {
    for (const item of items) {
      if (typeof item === "string") {
        includePage(item, source);
        continue;
      }
      if (item === null || typeof item !== "object") {
        errors.push(`${source} contains an invalid sidebar entry.`);
        continue;
      }
      if ("slug" in item && typeof item.slug === "string") {
        includePage(item.slug, source);
      }
      if ("link" in item && typeof item.link === "string") {
        includeLink(item.link, source, includePage, errors);
      }
      if ("autogenerate" in item) {
        includeDirectory(
          root,
          item.autogenerate,
          source,
          pages,
          includePage,
          errors,
        );
      }
      if ("items" in item) {
        if (!Array.isArray(item.items)) {
          errors.push(`${source} has a non-array items property.`);
        } else {
          visit(item.items, source);
        }
      }
      if (
        !("slug" in item) &&
        !("link" in item) &&
        !("autogenerate" in item) &&
        !("items" in item)
      ) {
        errors.push(`${source} contains an unrecognized sidebar entry.`);
      }
    }
  }
  visit(sidebar, "sidebar");

  for (const [route, page] of pagesByRoute) {
    if (route === "" || route === "404") {
      continue;
    }
    if (!includedPages.has(page)) {
      errors.push(`Published page "${page}" is missing from the sidebar.`);
    }
  }

  return errors;
}

/**
 * Resolve a Starlight external or local sidebar link.
 *
 * @param {string} link Sidebar link value.
 * @param {string} source Sidebar location for error reporting.
 * @param {(route: string, source: string) => void} includePage Page collector.
 * @param {string[]} errors Validation errors to update.
 * @returns {void}
 */
function includeLink(link, source, includePage, errors) {
  const url = new URL(link, SITE_ORIGIN);
  if (url.origin !== SITE_ORIGIN) {
    return;
  }
  includePage(url.pathname, source);
}

/**
 * Include every page below one Starlight autogenerated directory.
 *
 * @param {string} root Content root.
 * @param {unknown} options Autogenerate options.
 * @param {string} source Sidebar location for error reporting.
 * @param {string[]} pages All published page paths.
 * @param {(route: string, source: string) => void} includePage Page collector.
 * @param {string[]} errors Validation errors to update.
 * @returns {void}
 */
function includeDirectory(root, options, source, pages, includePage, errors) {
  if (
    options === null ||
    typeof options !== "object" ||
    !("directory" in options) ||
    typeof options.directory !== "string"
  ) {
    errors.push(`${source} has invalid autogenerate options.`);
    return;
  }

  const directory = path.resolve(root, options.directory);
  if (!isWithin(root, directory) || !existsSync(directory)) {
    errors.push(
      `${source} autogenerate directory "${options.directory}" is missing.`,
    );
    return;
  }

  const prefix = path.relative(root, directory).split(path.sep).join("/");
  const matches = pages.filter((page) => {
    const relative = path.relative(root, page).split(path.sep).join("/");
    return relative.startsWith(`${prefix}/`);
  });
  if (matches.length === 0) {
    errors.push(
      `${source} autogenerate directory "${options.directory}" has no pages.`,
    );
    return;
  }
  for (const page of matches) {
    const relative = path.relative(root, page).split(path.sep).join("/");
    includePage(routeForPage(relative), source);
  }
}

/**
 * Collect Markdown and MDX pages under the content root.
 *
 * @param {string} root Content root.
 * @returns {string[]} Absolute Markdown and MDX page paths.
 */
function collectMarkdownPages(root) {
  const pages = [];
  if (!existsSync(root)) {
    return pages;
  }

  /**
   * Visit a content directory recursively.
   *
   * @param {string} directory Directory to inspect.
   * @returns {void}
   */
  function visit(directory) {
    for (const entry of readdirSync(directory, { withFileTypes: true })) {
      if (entry.name.startsWith("_")) {
        continue;
      }
      const absolute = path.join(directory, entry.name);
      if (entry.isDirectory()) {
        visit(absolute);
      } else if (
        entry.isFile() &&
        entry.name !== "AGENTS.md" &&
        /\.(md|mdx|mdoc)$/i.test(entry.name)
      ) {
        pages.push(absolute);
      }
    }
  }

  visit(root);
  return pages;
}

/**
 * Convert a Starlight content path to its canonical route key.
 *
 * @param {string} relative Relative content path.
 * @returns {string} Canonical route key without leading or trailing slashes.
 */
function routeForPage(relative) {
  const withoutExtension = relative.replace(/\.(md|mdx|mdoc)$/i, "");
  return normalizeRoute(withoutExtension);
}

/**
 * Normalize route aliases such as a folder index and its slash form.
 *
 * @param {string} route Route or slug.
 * @returns {string} Canonical route key.
 */
function normalizeRoute(route) {
  let normalized = decodeURIComponent(route).replaceAll("\\", "/");
  normalized = normalized.replace(/^\/+|\/+$/g, "");
  normalized = normalized.replace(/\.(md|mdx|mdoc|html?)$/i, "");
  normalized = normalized.replace(/(?:^|\/)index$/i, "");
  return normalized.toLowerCase();
}

/**
 * Ensure a filesystem path remains under the documentation content root.
 *
 * @param {string} root Content root.
 * @param {string} candidate Candidate path.
 * @returns {boolean} Whether the candidate is contained in the root.
 */
function isWithin(root, candidate) {
  const relative = path.relative(root, candidate);
  return relative !== ".." && !relative.startsWith(`..${path.sep}`);
}

/**
 * Run the live documentation navigation check.
 *
 * @returns {void}
 */
function main() {
  const scriptDirectory = path.dirname(fileURLToPath(import.meta.url));
  const docsRoot = path.resolve(scriptDirectory, "../src/content/docs");
  const errors = validateDocumentationNavigation(
    docsRoot,
    documentationSidebar,
  );

  if (errors.length > 0) {
    for (const error of errors) {
      console.error(error);
    }
    process.exitCode = 1;
    return;
  }

  console.log("Documentation navigation check passed.");
}

if (
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  main();
}
